#!/usr/bin/env python3
"""Authoring source for Season 1 (episodes 1–8).

Writing eight variants of every text by hand in JSON is error-prone, so the
episodes are authored here in a compact form and written out as
episodes/epNN-*/episode.json + content.json (the files the reader and the
prompt builder use). Edit here, then run:

    python3 tools/authoring/season1.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

# default bubble boxes (the art for these episodes is not drawn yet; the
# illustrator places the tails when the panels exist)
POS = {"caption": (3, 4, 42), "caption2": (58, 82, 39), "speech": (50, 6, 40), "speech2": (8, 30, 38), "shout": (50, 6, 38), "whisper": (60, 30, 36)}


def B(kind, en, ru, who=None, slot=None):
    x, y, w = POS[slot or kind]
    b = {"kind": "caption" if kind.startswith("caption") else kind, "x": x, "y": y, "w": w, "text": {"en": en, "ru": ru}}
    if who:
        b["who"] = who
    return b


def P(pid, verses, chars, camera, kids_scene, adults_scene, kids, adults):
    return {"id": pid, "verses": verses, "characters": chars, "camera": camera,
            "scene": {"kids": kids_scene, "adults": adults_scene}, "bubbles": {"kids": kids, "adults": adults}}


def T(source, where, en_kids, ru_kids, en_ad, ru_ad):
    """Teacher paraphrase in four variants."""
    return {"source": source, "where": where, "k": (en_kids, ru_kids), "a": (en_ad, ru_ad)}


def build(ep):
    d = ROOT / "episodes" / ep["id"]
    d.mkdir(parents=True, exist_ok=True)
    episode = {k: ep[k] for k in ("id", "number", "season", "ref", "parallels", "title", "subtitle", "place", "panels")}
    episode["cover"] = f"ep{ep['number']:02d}"
    (d / "episode.json").write_text(json.dumps(episode, ensure_ascii=False, indent=2) + "\n")
    content = {"shared": ep["shared"]}
    for tr in ("orthodox", "protestant"):
        src = ep[tr]
        content[tr] = {}
        for age in ("kids", "adults"):
            content[tr][age] = {}
            for li, lang in enumerate(("en", "ru")):
                ts = [t for t in src["teachers"] if (t["k"][0] if age == "kids" else t["a"][0])]
                content[tr][age][lang] = {
                    "teachers": [{"source": t["source"], "kind": "paraphrase", "verify": True,
                                  "where": t["where"][li] if isinstance(t["where"], tuple) else t["where"],
                                  "text": (t["k"] if age == "kids" else t["a"])[li]} for t in ts],
                    "bigIdea": src[age]["bigIdea"][lang],
                    "apply": src[age]["apply"][lang],
                    "questions": src[age]["questions"][lang],
                    "memoryVerse": src[age]["memoryVerse"][lang],
                    "prayer": src[age]["prayer"][lang],
                }
    (d / "content.json").write_text(json.dumps(content, ensure_ascii=False, indent=2) + "\n")


def MV(ref_en, en, ref_ru, ru):
    return {"en": {"ref": ref_en, "text": en}, "ru": {"ref": ref_ru, "text": ru}}


def AP(*items):
    """items: (title_en, text_en, title_ru, text_ru)"""
    return {"en": [{"title": a, "text": b} for a, b, _, _ in items], "ru": [{"title": c, "text": d} for _, _, c, d in items]}


def Q(en, ru):
    return {"en": en, "ru": ru}


def BI(t_en, x_en, t_ru, x_ru, refs=None):
    out = {"en": {"title": t_en, "text": x_en}, "ru": {"title": t_ru, "text": x_ru}}
    if refs:
        out["en"]["refs"] = [{"ref": r[0], "text": r[1]} for r in refs]
        out["ru"]["refs"] = [{"ref": r[2], "text": r[3]} for r in refs]
    return out


def SH(kids_en, kids_ru, ad_en, ad_ru):
    return {"kids": {"en": kids_en, "ru": kids_ru}, "adults": {"en": ad_en, "ru": ad_ru}}


def WH(paras, bg):
    return {"whatHappened": paras, "background": [{"term": a, "text": b} for a, b in bg]}


